import { describe, expect, it } from "vitest";
import { simulate, type Agent, type Target } from "../src/steering.js";
import { vec } from "../src/vec.js";

// Shared parameters per the spec:
// - target moves in a straight line at speed 3
// - agent max speed 5
// - identical starting offset for both strategies within a geometry
const AGENT_SPEED = 5;
const TARGET_SPEED = 3;
const RADIUS = 1;

function makeAgent(offsetFrom: ReturnType<typeof vec>): Agent {
  return {
    pos: offsetFrom,
    vel: vec(0, 0),
    maxSpeed: AGENT_SPEED,
    maxForce: 8,
  };
}

function makeTarget(pos: ReturnType<typeof vec>, dir: ReturnType<typeof vec>): Target {
  return { pos, vel: dir };
}

interface Geometry {
  name: string;
  agentOffset: ReturnType<typeof vec>; // same start for seek and pursuit
  targetPos: ReturnType<typeof vec>;
  targetDir: ReturnType<typeof vec>;
}

const geometries: Geometry[] = [
  // Crossing: agent left of the target's lane, target sweeps horizontally past.
  {
    name: "crossing",
    agentOffset: vec(0, 0),
    targetPos: vec(10, 20),
    targetDir: vec(-1, 0), // heading left across the agent's column
  },
  // Trailing: agent directly behind a slower target fleeing straight ahead.
  {
    name: "trailing",
    agentOffset: vec(0, 0),
    targetPos: vec(0, 40),
    targetDir: vec(0, 1), // fleeing up the +y axis
  },
  // Head-on offset: target approaching the agent's general area but laterally offset.
  {
    name: "head-on offset",
    agentOffset: vec(0, 0),
    targetPos: vec(25, 6),
    targetDir: vec(-1, 0), // driving toward/past the agent
  },
];

describe("seek vs pursuit interception", () => {
  for (const g of geometries) {
    it(`${g.name}: both intercept, pursuit strictly earlier`, () => {
      const seekRun = simulate(makeAgent(g.agentOffset), makeTarget(g.targetPos, g.targetDir), "seek", RADIUS);
      const pursuitRun = simulate(
        makeAgent(g.agentOffset),
        makeTarget(g.targetPos, g.targetDir),
        "pursuit",
        RADIUS
      );

      // Deterministic: rerunning yields identical trajectories.
      const seekAgain = simulate(makeAgent(g.agentOffset), makeTarget(g.targetPos, g.targetDir), "seek", RADIUS);
      const pursuitAgain = simulate(
        makeAgent(g.agentOffset),
        makeTarget(g.targetPos, g.targetDir),
        "pursuit",
        RADIUS
      );
      expect(seekRun.trajectory).toEqual(seekAgain.trajectory);
      expect(pursuitRun.trajectory).toEqual(pursuitAgain.trajectory);

      console.log(
        `[${g.name}] seek intercept tick:     ${seekRun.tick}\n` +
          `[${g.name}] pursuit intercept tick: ${pursuitRun.tick}`
      );

      expect(seekRun.tick, "seek should eventually intercept").not.toBeNull();
      expect(pursuitRun.tick, "pursuit should eventually intercept").not.toBeNull();
      expect(pursuitRun.tick!).toBeLessThan(seekRun.tick!);
    });
  }
});

