import { add, dist, limit, normalize, scale, sub, vec, type Vec2 } from "./vec.js";

export interface Target {
  pos: Vec2;
  /** Velocity, applied as pos += vel * dt each tick. */
  vel: Vec2;
}

export interface Agent {
  pos: Vec2;
  vel: Vec2;
  maxSpeed: number;
  maxForce: number;
}

export type Strategy = "seek" | "pursuit";

export interface RunResult {
  /** Tick at which distance < radius (1-indexed), or null if never within maxTicks. */
  tick: number | null;
  trajectory: { agent: Vec2; target: Vec2; t: number }[];
}

/**
 * Seek: steer toward the target's CURRENT position.
 * Pursuit: steer toward the target's position extrapolated by
 *          distance(agent, target) / agent.maxSpeed ticks.
 *
 * Fixed dt = 1 and pure arithmetic => fully deterministic trajectories.
 */
export function simulate(
  agentStart: Agent,
  targetStart: Target,
  strategy: Strategy,
  interceptRadius = 1,
  maxTicks = 5000
): RunResult {
  const agent: Agent = { ...agentStart, pos: { ...agentStart.pos }, vel: { ...agentStart.vel } };
  const target: Target = { pos: { ...targetStart.pos }, vel: { ...targetStart.vel } };
  const dt = 1;
  const trajectory: RunResult["trajectory"] = [];

  for (let t = 1; t <= maxTicks; t++) {
    // --- steering decision based on state at start of tick ---
    let goal: Vec2;
    if (strategy === "seek") {
      goal = target.pos;
    } else {
      const d = dist(agent.pos, target.pos);
      const lookAhead = d / agent.maxSpeed;
      goal = add(target.pos, scale(target.vel, lookAhead));
    }

    // Classic Reynolds steering: desired velocity toward the goal,
    // steering force = desired - current velocity, clamped by maxForce.
    const desired = scale(normalize(sub(goal, agent.pos)), agent.maxSpeed);
    const steer = limit(sub(desired, agent.vel), agent.maxForce);

    // --- Euler integration ---
    agent.vel = limit(add(agent.vel, scale(steer, dt)), agent.maxSpeed);
    agent.pos = add(agent.pos, scale(agent.vel, dt));
    target.pos = add(target.pos, scale(target.vel, dt));

    trajectory.push({ agent: { ...agent.pos }, target: { ...target.pos }, t });

    if (dist(agent.pos, target.pos) < interceptRadius) {
      return { tick: t, trajectory };
    }
  }

  return { tick: null, trajectory };
}

